13		"github.com/alicegogogogogo/local-first-sync-service/internal/store"
14	)
15	
16	// maxBatchBytes caps an inbound POST body.
17	const maxBatchBytes = 10 << 20
18	
19	// defaultListLimit is used when GET omits limit.
20	const defaultListLimit = 100
21	
22	// maxListLimit is the largest page size GET accepts.
23	const maxListLimit = 1000
24	
25	type changeIn struct {
26		ID      string          `json:"id"`
27		Payload json.RawMessage `json:"payload"`
28	}
29	
30	type postRequest struct {
31		DeviceID string     `json:"deviceId"`
32		Changes  []changeIn `json:"changes"`
33	}
34	
35	type mergeChangeIn struct {
36		ID      string          `json:"id"`
37		Payload json.RawMessage `json:"payload"`
38	}
