70	// NewHandler builds the public HTTP surface backed by s.
71	func NewHandler(s *store.Store) http.Handler {
72		mux := http.NewServeMux()
73	
74		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
75			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
76		})
77	
78		mux.HandleFunc("POST /v1/devices", func(w http.ResponseWriter, r *http.Request) {
79			handleRegisterDevice(s, w, r)
80		})
81		// Non-POST verbs on the exact collection path: the method-less pattern is
82		// less specific than POST above, so it only catches the rest and answers a
83		// JSON 404 instead of ServeMux's slash redirect.
84		mux.HandleFunc("/v1/devices", func(w http.ResponseWriter, _ *http.Request) {
85			writeError(w, http.StatusNotFound, "unknown device path")
86		})
87		mux.HandleFunc("/v1/sessions", func(w http.ResponseWriter, _ *http.Request) {
88			writeError(w, http.StatusNotFound, "unknown session path")
89		})
90		mux.HandleFunc("POST /v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, r *http.Request) {
91			handleCreateSession(s, w, r)
92		})
93		mux.HandleFunc("DELETE /v1/devices/{deviceId}/sessions/{sessionId}", func(w http.ResponseWriter, r *http.Request) {
94			handleDeleteSession(s, w, r)
95		})
96		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments", func(w http.ResponseWriter, r *http.Request) {
97			handleCreateAttachment(s, w, r)
98		})
99		mux.HandleFunc("PUT /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
100			handlePutChunk(s, w, r)
101		})
102		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments/{attachmentId}/complete", func(w http.ResponseWriter, r *http.Request) {
103			handleCompleteAttachment(s, w, r)
104		})
105		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}", func(w http.ResponseWriter, r *http.Request) {
106			handleGetAttachment(s, w, r)
107		})
108		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
109			handleGetChunk(s, w, r)
110		})
111		mux.HandleFunc("GET /v1/sessions/{sessionId}/documents/{documentId}/changes", func(w http.ResponseWriter, r *http.Request) {
112			handleSessionChanges(s, w, r)
113		})
114		// Any other path under the new namespaces is a JSON 404 rather than
115		// ServeMux's plain-text one: every failure of a new endpoint answers JSON.
116		// Exact method-patterns above take precedence over these subtree patterns.
117		mux.HandleFunc("/v1/devices/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
118			writeError(w, http.StatusNotFound, "unknown device/session path")
119		})
120		mux.HandleFunc("/v1/sessions/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
121			writeError(w, http.StatusNotFound, "unknown session path")
122		})
123	
124		mux.HandleFunc("POST /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
125			handlePostChanges(s, w, r)
126		})
127		mux.HandleFunc("GET /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
128			handleListChanges(s, w, r)
129		})
130		mux.HandleFunc("POST /v1/documents/{documentID}/merge", func(w http.ResponseWriter, r *http.Request) {
131			handleMergeChange(s, w, r)
132		})
133		mux.HandleFunc("POST /v1/documents/{documentID}/snapshots", func(w http.ResponseWriter, r *http.Request) {
134			handlePostSnapshot(s, w, r)
135		})
136		mux.HandleFunc("GET /v1/documents/{documentID}/snapshots/{cursor}", func(w http.ResponseWriter, r *http.Request) {
137			handleGetSnapshot(s, w, r)
138		})
139		mux.HandleFunc("POST /v1/documents/{documentID}/restore", func(w http.ResponseWriter, r *http.Request) {
140			handleRestore(s, w, r)
141		})
142		mux.HandleFunc("POST /v1/documents/{documentID}/permissions", func(w http.ResponseWriter, r *http.Request) {
143			handleSetPermission(s, w, r)
144		})
145	
146		// ServeMux treats any empty path segment (the doubled slash in
147		// /v1/documents//..., /v1/devices//sessions or
148		// /v1/sessions//documents/...) as an unclean path and answers with a 307
149		// HTML redirect (a 404 in a real client). The API contract is a 400 JSON
150		// error for an empty identifier, so intercept those paths before the mux
151		// sees them. A trailing slash empties the final id of the device/session
152		// routes and is rejected there for the same reason; the document routes
153		// keep their pre-existing ServeMux behavior.
154		return emptyIDGuard(mux)
155	}
156	
157	// emptyIDGuard rejects requests carrying an empty path identifier with a 400
158	// JSON error instead of letting ServeMux emit its HTML redirect or a
159	// plain-text 404.
160	//
161	// The document family keeps its original rule (an empty documentID, i.e. the
162	// prefix /v1/documents//); other odd paths there retain their old response so
163	// the pre-existing surface is unchanged. The new device/session families are
164	// stricter: any doubled slash (an empty deviceId, sessionId or documentId
165	// segment) or a trailing slash (an empty final id) is a 400 JSON error.
166	func emptyIDGuard(next http.Handler) http.Handler {
167		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
168			p := r.URL.Path
169	
170			documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
171			newFamilySegmentEmpty := false
172			if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
173				newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
174			}
175	
176			if documentSegmentEmpty || newFamilySegmentEmpty {
177				writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
178				return
179			}
180			next.ServeHTTP(w, r)
181		})
182	}
