184	// Handler exposes the HTTP surface over a private in-memory store. Use
185	// NewHandler with a durable store for real deployments.
186	func Handler() http.Handler {
187		s, err := store.Open("")
188		if err != nil {
189			log.Fatalf("open in-memory store: %v", err)
190		}
191		return NewHandler(s)
192	}
