221	func handleRegisterDevice(s *store.Store, w http.ResponseWriter, r *http.Request) {
222		var req deviceRequest
223		if !decodeJSONBody(w, r, &req) {
224			return
225		}
226		if req.DeviceID == "" {
227			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
228			return
229		}
230	
231		created, err := s.RegisterDevice(req.DeviceID)
232		if err != nil {
233			writeError(w, http.StatusInternalServerError, "failed to register device")
234			return
235		}
236	
237		writeJSON(w, http.StatusOK, map[string]any{"deviceId": req.DeviceID, "created": created})
238	}
