349	func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
350		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
351	
352		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
353		if err != nil || mediaType != "application/json" {
354			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
355			return
356		}
357	
358		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
359		var req mergeRequest
360		dec := json.NewDecoder(r.Body)
361		if err := dec.Decode(&req); err != nil {
362			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
363			return
364		}
365		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
366			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
367			return
368		}
369	
370		if req.DeviceID == "" {
371			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
372			return
373		}
374		// baseCursor must be present and a non-negative integer (no fractions,
375		// strings, booleans or null).
376		if len(req.BaseCursor) == 0 {
377			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
378			return
379		}
380		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
381		if !ok {
382			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
383			return
384		}
385		if req.Change == nil {
386			writeError(w, http.StatusBadRequest, "change must be an object")
387			return
388		}
389		if req.Change.ID == "" {
390			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
391			return
392		}
393		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
394			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
395			return
396		}
397	
398		result, err := s.MergeChange(documentID, baseCursor, store.Change{
399			ID:       req.Change.ID,
400			DeviceID: req.DeviceID,
401			Payload:  req.Change.Payload,
402		})
403		if err != nil {
404			var conflict *store.ErrConflict
405			switch {
406			case errors.Is(err, store.ErrStaleCursor):
407				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
408				return
409			case errors.As(err, &conflict):
410				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
411				return
412			default:
413				writeError(w, http.StatusInternalServerError, "failed to merge change")
414				return
415			}
416		}
417	
418		writeJSON(w, http.StatusOK, result)
419	}
