553	// handleSetPermission grants or revokes a registered device's access to one
554	// document. Devices start authorized, so the first revoke is the first write;
555	// repeating the current state is idempotent (changed=false). A rejected
556	// request (bad content type, malformed JSON, trailing content, empty or
557	// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
558	// unregistered device is a 404 JSON error.
559	func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
560		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
561	
562		var req permissionRequest
563		if !decodeJSONBody(w, r, &req) {
564			return
565		}
566		if req.DeviceID == "" {
567			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
568			return
569		}
570		var authorized bool
571		switch req.Action {
572		case "grant":
573			authorized = true
574		case "revoke":
575			authorized = false
576		default:
577			writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
578			return
579		}
580	
581		changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
582		if err != nil {
583			if errors.Is(err, store.ErrDeviceNotFound) {
584				writeError(w, http.StatusNotFound, "device not found")
585				return
586			}
587			writeError(w, http.StatusInternalServerError, "failed to update permission")
588			return
589		}
590	
591		writeJSON(w, http.StatusOK, map[string]any{
592			"deviceId":   req.DeviceID,
593			"authorized": authorized,
594			"changed":    changed,
595		})
596	}
