1	package server
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"net/http"
8		"net/http/httptest"
9		"path/filepath"
10		"strings"
11		"sync"
12		"testing"
13	
14		"github.com/alicegogogogogo/local-first-sync-service/internal/store"
15	)
16	
17	func newTestHandler(t *testing.T) (http.Handler, *store.Store) {
18		t.Helper()
19		s, err := store.Open(filepath.Join(t.TempDir(), "test.db"))
20		if err != nil {
21			t.Fatal(err)
22		}
23		t.Cleanup(func() { _ = s.Close() })
24		return NewHandler(s), s
25	}
26	
27	func postJSON(t *testing.T, h http.Handler, url string, body any) (*httptest.ResponseRecorder, map[string]any) {
28		t.Helper()
29		var r *http.Request
30		switch b := body.(type) {
31		case string:
32			r = httptest.NewRequest(http.MethodPost, url, strings.NewReader(b))
33		case []byte:
34			r = httptest.NewRequest(http.MethodPost, url, bytes.NewReader(b))
35		default:
36			raw, _ := json.Marshal(b)
37			r = httptest.NewRequest(http.MethodPost, url, bytes.NewReader(raw))
38		}
39		if body != nil {
40			r.Header.Set("Content-Type", "application/json")
41		}
42		w := httptest.NewRecorder()
43		h.ServeHTTP(w, r)
44		var decoded map[string]any
45		if w.Body.Len() > 0 {
46			_ = json.Unmarshal(w.Body.Bytes(), &decoded)
47		}
48		return w, decoded
49	}
50	
51	func doRequest(t *testing.T, h http.Handler, method, url string) (*httptest.ResponseRecorder, map[string]any) {
52		t.Helper()
53		w := httptest.NewRecorder()
54		h.ServeHTTP(w, httptest.NewRequest(method, url, nil))
55		var decoded map[string]any
56		if w.Body.Len() > 0 {
57			_ = json.Unmarshal(w.Body.Bytes(), &decoded)
58		}
59		return w, decoded
60	}
61	
62	func TestHealth(t *testing.T) {
63		h, _ := newTestHandler(t)
64		w, body := doRequest(t, h, http.MethodGet, "/healthz")
65		if w.Code != http.StatusOK {
66			t.Fatalf("status = %d, want %d", w.Code, http.StatusOK)
67		}
68		if got := w.Header().Get("Content-Type"); got != "application/json" {
69			t.Fatalf("content type = %q", got)
70		}
71		if body["status"] != "ok" {
72			t.Fatalf("body = %s", w.Body.String())
73		}
74	}
75	
76	func TestPostValidBatch(t *testing.T) {
77		h, _ := newTestHandler(t)
78		w, body := postJSON(t, h, "/v1/documents/doc1/changes", map[string]any{
79			"deviceId": "dev-A",
80			"changes": []map[string]any{
81				{"id": "c1", "payload": map[string]any{"text": "hello"}},
82				{"id": "c2", "payload": []any{1, 2, 3}},
83			},
84		})
85		if w.Code != http.StatusOK {
86			t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
87		}
88		results, ok := body["results"].([]any)
89		if !ok || len(results) != 2 {
90			t.Fatalf("results = %v", body["results"])
91		}
92		r0 := results[0].(map[string]any)
93		if r0["id"] != "c1" || r0["created"] != true || r0["cursor"].(float64) != 1 {
94			t.Fatalf("r0 = %v", r0)
95		}
96		r1 := results[1].(map[string]any)
97		if r1["id"] != "c2" || r1["cursor"].(float64) != 2 {
98			t.Fatalf("r1 = %v", r1)
99		}
100	}
101	
102	func TestPostRejectsBadInput(t *testing.T) {
103		h, s := newTestHandler(t)
104		url := "/v1/documents/doc1/changes"
105		if _, err := s.PostChanges("doc1", []store.Change{
106			{ID: "existing", DeviceID: "dev", Payload: json.RawMessage(`{"v":1}`)},
107		}); err != nil {
108			t.Fatal(err)
109		}
110	
111		cases := []struct {
112			name        string
113			contentType string
114			body        string
115			wantStatus  int
116		}{
117			{"wrong content type", "text/plain", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
118			{"missing content type", "", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
119			{"content type with json suffix", "application/vnd.api+json", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
120			{"malformed json", "application/json", `{"deviceId":"d","changes":[`, http.StatusBadRequest},
121			{"trailing content", "application/json", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}garbage`, http.StatusBadRequest},
122			{"empty deviceId", "application/json", `{"deviceId":"","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
123			{"missing deviceId", "application/json", `{"changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
124			{"numeric deviceId", "application/json", `{"deviceId":7,"changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
125			{"empty changes", "application/json", `{"deviceId":"d","changes":[]}`, http.StatusBadRequest},
126			{"missing changes", "application/json", `{"deviceId":"d"}`, http.StatusBadRequest},
127			{"empty id", "application/json", `{"deviceId":"d","changes":[{"id":"","payload":1}]}`, http.StatusBadRequest},
128			{"numeric id", "application/json", `{"deviceId":"d","changes":[{"id":123,"payload":1}]}`, http.StatusBadRequest},
129			{"missing payload", "application/json", `{"deviceId":"d","changes":[{"id":"a"}]}`, http.StatusBadRequest},
130			{"duplicate ids in batch", "application/json", `{"deviceId":"d","changes":[{"id":"a","payload":1},{"id":"a","payload":2}]}`, http.StatusBadRequest},
131			{"conflicting existing", "application/json", `{"deviceId":"d","changes":[{"id":"existing","payload":2}]}`, http.StatusConflict},
132			{"conflict device mismatch", "application/json", `{"deviceId":"other","changes":[{"id":"existing","payload":{"v":1}}]}`, http.StatusConflict},
133		}
134	
135		for _, tc := range cases {
