		{"missing content type", "", `{"cursor":1,"state":{}}`},
		{"malformed json", "application/json", `{"cursor":1,"state":`},
		{"trailing content", "application/json", `{"cursor":1,"state":{}}garbage`},
		{"missing cursor", "application/json", `{"state":{}}`},
