// GetAttachmentChunk returns the bytes stored at index. An unknown attachment
// yields ErrAttachmentNotFound, a non-creator device ErrAttachmentForbidden, a
// negative index or one beyond the declared chunk count *ErrChunkInvalid (the
// attachment exists, so the illegal index is a 400 rather than a missing
// chunk), and an in-range index with no stored chunk ErrChunkNotFound.
func (s *Store) GetAttachmentChunk(deviceID, attachmentID string, index int64) ([]byte, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := getAttachmentTx(tx, attachmentID, deviceID)
	if err != nil {
		return nil, err
	}
	if index < 0 || index >= a.chunkCount() {
		return nil, &ErrChunkInvalid{Reason: fmt.Sprintf("chunk index %d is out of range [0, %d)", index, a.chunkCount())}
	}

