cat > internal/server/zz_probe_test.go <<'EOF'
package server

import (
	"crypto/sha256"
	"encoding/hex"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestProbeDigestSizeConflict(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")

	// Craft two different byte strings with the same sha256 is infeasible, so
	// instead complete att-A, then declare att-B with att-A's digest but a
	// different size and upload B's real bytes. On complete, content hash is
	// computed over B's bytes; it must equal B's *declared* digest (which is
	// A's digest) — impossible with different content. So instead declare B's
	// digest honestly but collide in the contents table: not possible unless
	// hashes match. Use the designed collision path by inserting same digest
	// with a differing size via two uploads of identical bytes but different
	// declared totalBytes — which PUT shape validation forbids. So the
	// realistic trigger: A completed of size S; B declares same digest but size
	// S' and uploads S' bytes that ALSO hash to the digest. Can't happen with
	// sha256. Confirm the branch is reachable only via DB seeded differently:
	_ = sha256.New
	_ = hex.EncodeToString
	content := []byte("abcdef")
	d := sha256.Sum256(content)
	_ = d
	mustCreateAttachment(t, h, "dev-1", "att-a", content, 4)
	putChunk(t, h, "dev-1", "att-a", 0, content[:4])
	putChunk(t, h, "dev-1", "att-a", 1, content[4:])
	w, body := completeAttachment(t, h, "dev-1", "att-a")
	t.Logf("A complete %d %v", w.Code, body)

	// B declares A's digest with a different size; uploads its own 4 bytes that
	// happen to hash differently -> 422 (digest mismatch), demonstrating the
	// 409 branch needs a true digest collision which is exercised at store unit
	// level.
	mustCreateAttachment(t, h, "dev-2", "att-b", []byte("wxyz"), 4)
	createAttachment(t, h, "dev-2", "att-b2", 4, 4, hex.EncodeToString(d[:]))
	putChunk(t, h, "dev-2", "att-b2", 0, []byte("wxyz"))
	w, body = completeAttachment(t, h, "dev-2", "att-b2")
	t.Logf("B2 complete (422 expected) %d %v", w.Code, body)

	r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-2/attachments/att-b2", nil)
	w = serveRecorder(h, r)
	t.Logf("B2 meta after: %d %s", w.Code, w.Body.String())
}
EOF
go test ./internal/server/ -run TestProbeDigestSizeConflict -v 2>&1 | tail -12
rm internal/server/zz_probe_test.go

